  "plans.title": "Муқоисаи нақшаҳои StockHaven",
  "plans.intro": "Як ҳисоб, новобаста аз он ки шумо кадом нақшаро интихоб мекунед — Business то панҷ тиҷоратро фаро мегирад. Нархҳо моҳона бо доллари ИМА мебошанд ва муштариёни нави ҳақдори вебсайт метавонанд як озмоиши ҳафтрӯзаро дар Essentials ва Business гиранд. Баланд бардоштани обунаи мавҷудаи Essentials ба Business озмоишро аз нав оғоз намекунад ва озмоиши ройгони дигар эҷод намекунад. Нархҳои нақшаи вебсайт пеш аз андозҳои татбиқшаванда мебошанд, агар бошанд. Пардохти дақиқи шумо пеш аз он ки шумо обунаро иҷозат диҳед, нишон дода мешавад.",
