  "plans.mobileIncludedNote": "Ҳарду нақшаи вебсайт ҳамроҳи мобилиро дар бар мегиранд, бинобар ин обунашудаи вебсайт ҳеҷ гоҳ ҳаққи моҳонаи мобилиро низ намепардозад.",
  "plans.priceNote": "Essentials $14.99/моҳ илова бар андозҳои татбиқшаванда аст, агар бошанд. Business $29.99/моҳ илова бар андозҳои татбиқшаванда аст, агар бошанд. Ҳама гуна андози талабшаванда ҳангоми пардохти провайдер муайян карда мешавад ва бояд пеш аз пардохт дар маблағи ниҳоӣ пайдо шавад. Ин саҳифаи муқоиса пешниҳоди андоз ё иҷозати пардохт нест.",
  "plans.mobilePriceNote": "Нақшаи танҳо мобилӣ $4.99/моҳ бо нархи асосии пешбинишудаи ИМА аст. App Store ё Google Play нархи воқеии обунаи маҳаллӣ ва ҳама гуна андозҳои татбиқшавандаро пеш аз харид нишон медиҳад. Иҷозатҳои маҳсулот, сайт ва кормандони он дар оғоз, ҷудогона аз сатҳҳои вебсайт муқаррар карда мешаванд.",
  "plans.planChangeNote": "Тағйири нақшаи вебсайт бояд аз ҷониби провайдери ҳисобдорӣ тасдиқ карда шавад. Нархи нав, санаи эътибор ва ҳама гуна таносуби нарх пеш аз иҷозат додани тағйирот шарҳ дода мешаванд. Баландбарӣ набояд обунаи дуюмро эҷод кунад.",
  "plans.providerNote": "Нархҳо, пардохтҳо ва озмоишҳо аз ҷониби провайдере идора карда мешаванд, ки шумо тавассути он обуна мешавед — App Store, Google Play, вебсайт ё Shopify — ҳеҷ гоҳ аз ҷониби ин саҳифа не.",
