  "materials.tookApart": "{amount} × {name} дар {location} ҷудо шуд · {reference}. Қисмҳо боз дар рафанд; {remaining} монд.",
  "exports.eyebrow": "Маълумот",
  "exports.title": "Содирот ва нусхаҳои эҳтиётӣ",
  "exports.subtitleStart": "Боргириҳо ҳамеша маҳдуданд ба",
  "exports.subtitleRest": ". Ҳар файл бо номи тиҷорат ва санаи сохта шуданаш қайд карда мешавад.",
  "exports.createBusinessFirst": "Аввал тиҷорат эҷод кунед — содирот ба тиҷорат тааллуқ дорад, на ба барнома.",
  "exports.lockedTitle": "Содироти CSV ва Excel хусусияти Business аст",
  "exports.lockedDesc": "Фазои кории шумо дар нақшаи Essentials аст. Business содироти CSV ва Excel, арзёбии захира, маҳсулот ва кормандони номаҳдуд, таъминкунандагон, харид ва маҷмӯаҳоро илова мекунад.",
  "exports.seeBusiness": "Дидани он чи Business дар бар мегирад",
  "exports.whatTheseAre": "Ин файлҳо чистанд",
  "exports.about1": "Ҳар маҷмӯи маълумот ҳамчун CSV ё китоби кории воқеии Excel (.xlsx) меояд — китоби кории пурраи инвентар танҳо Excel аст, бо як варақ барои ҳар маҷмӯи маълумот. Файлҳои CSV дар Excel, Numbers, Google Sheets ва аксари барномаҳои захира кушода мешаванд. Матни UTF-8, вергулҳои овардашуда, танаффусҳои сатр дар қайдҳо ва сифрҳои пеш дар рамзҳо ҳама нигоҳ дошта мешаванд ва ҳуҷайраҳое, ки мисли формула оғоз мешаванд, безарар карда мешаванд, то ҷадвал онҳоро ҳамчун матн кушояд.",
  "exports.about2": "Дар файлҳои Excel, SKU-ҳо, UPC-ҳо, ISBN-ҳо ва штрих-кодҳо ҳуҷайраҳои матнӣ мебошанд — ҳеҷ гоҳ қайдҳои илмӣ не ва ҳеҷ гоҳ сифрҳои буридашуда не — бо дарозии сутунҳо, филтрҳои сарлавҳа ва форматҳои асъор ё миқдор татбиқ карда шудаанд. Китоби кории пурраи инвентар маҳсулот, сатҳи захира, маконҳо ва ҳаракатҳоро дар варақҳои ҷудогона нигоҳ медорад.",
  "exports.about3": "Содиротҳои хеле калон дар 20,000 сатр барои ҳар маҷмӯи маълумот қатъ мешаванд — вақте ин рух медиҳад, номи файл онро мегӯяд (truncated-20000), бинобар ин файли қисмӣ ҳеҷ гоҳ ҳамчун пурра намегузарад.",
  "exports.about4": "Нусхаи эҳтиётӣ акси маълумоти шумост, на барқароркунии як ламс. Барқарор кардани он кори дастӣ ва аввал баррасишаванда аст, бинобар ин файлро бехатар нигоҳ доред — ҳеҷ чиз дар барнома ҳанӯз наметавонад тиҷорати нестшударо аз он аз нав эҷод кунад. Рамзи барнома ва нусхаҳои эҳтиётии платформаи Base44 аз ин файлҳо ҷудогона идора карда мешаванд.",
  "exports.about5": "Аксҳо ва замимаҳо ҳамчун пайвандҳои нигоҳдошташудаашон номбар карда мешаванд — файлҳои тасвирӣ худашон ба боргирӣ бастабандӣ карда намешаванд.",
  "exports.backupTitle": "Нусхаи эҳтиётии пурра",
  "exports.backupDesc": "Як файл бо маҳсулот, маконҳо, сатҳи захира, дафтари пурраи ҳаракат, таъминкунандагон, харид, фармоишҳо, бозгаштҳо, ҳисобҳо ва рӯйхатҳои ин тиҷорат — илова бар танзимоти профили он. Онро дар ҷое нигоҳ доред, ки шумо назорат мекунед.",
  "exports.backupIncludes1": "Маҳсулот, рамзҳо, арзишҳо ва қайдҳо",
  "exports.backupIncludes2": "Маконҳо ва миқдорҳо барои ҳар макон",
