  "settings.pastDue.body": "Пардохти охирини шумо анҷом нашуд. Усули пардохти худро аз саҳифаи Баландбарӣ навсозӣ кунед — Stripe бо ҷадвали худ аз нав кӯшиш мекунад ва обунаи шумо барвақт бекор карда намешавад. Агар шумо намедонед, ки чӣ кунед, бо дастгирӣ дар theluminousbookshop@outlook.com тамос гиред.",
