  "settings.switcher.new": "Нав",
  "settings.switcher.newDescription": "Ҳар тиҷорат маҳсулот, маконҳо, таъминкунандагон ва фармоишҳои хариди худро нигоҳ медорад. Ҳеҷ чиз байни онҳо мубодила карда намешавад.",
